import React, { useEffect, useMemo, useRef, useState } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import ProductCard from '../components/ProductCard';
import { getFeaturedProducts, getProductCategories, getProducts } from '../services/api';
import { useTheme } from '../context/ThemeContext';

const HomeRebuild = () => {
  const { isDarkMode } = useTheme();
  const navigate = useNavigate();
  const [searchParams, setSearchParams] = useSearchParams();
  const search = searchParams.get('search') || '';
  const category = searchParams.get('category') || '';
  const [featured, setFeatured] = useState([]);
  const [searchedProducts, setSearchedProducts] = useState([]);
  const [categories, setCategories] = useState([]);
  const [loading, setLoading] = useState(true);
  const categoriesScrollerRef = useRef(null);

  useEffect(() => {
    let active = true;

    const load = async () => {
      try {
        setLoading(true);
        const [featuredRes, categoriesRes] = await Promise.all([
          getFeaturedProducts(),
          getProductCategories()
        ]);
        if (!active) return;
        setFeatured(Array.isArray(featuredRes.data) ? featuredRes.data : []);
        setCategories(Array.isArray(categoriesRes.data) ? categoriesRes.data : []);
      } catch (error) {
        if (!active) return;
        setFeatured([]);
        setCategories([]);
      } finally {
        if (active) setLoading(false);
      }
    };

    load();
    return () => {
      active = false;
    };
  }, []);

  useEffect(() => {
    const style = document.createElement('style');
    style.textContent = `
      .hide-scrollbar::-webkit-scrollbar { display: none; }
      .hide-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }
    `;
    document.head.appendChild(style);
    return () => document.head.removeChild(style);
  }, []);

  const quickCategories = useMemo(() => categories.slice(0, 8), [categories]);
  const hasFilters = Boolean(search.trim() || category);
  const activeTabIndex = useMemo(() => {
    if (!category) return 0;
    const idx = quickCategories.findIndex((c) => c === category);
    return idx >= 0 ? idx + 1 : 0;
  }, [category, quickCategories]);

  const getCategoryIcon = (cat) => {
    const key = String(cat || '').toLowerCase();
    if (key.includes('milk')) return '🥛';
    if (key.includes('ghee')) return '🫙';
    if (key.includes('butter')) return '🧈';
    if (key.includes('cheese')) return '🧀';
    if (key.includes('curd') || key.includes('yogurt')) return '🥣';
    if (key.includes('paneer')) return '🧊';
    if (key.includes('cream')) return '🍦';
    if (key.includes('lassi') || key.includes('buttermilk')) return '🥤';
    if (key.includes('sweet')) return '🍬';
    return '🛍️';
  };

  const handleCategoryWheel = (e) => {
    const scroller = categoriesScrollerRef.current;
    if (!scroller) return;

    if (Math.abs(e.deltaY) < Math.abs(e.deltaX)) return;
    e.preventDefault();

    const step = 96; // One category card width
    const direction = e.deltaY > 0 ? 1 : -1;
    scroller.scrollBy({ left: direction * step, behavior: 'smooth' });
  };

  useEffect(() => {
    let active = true;

    const loadFiltered = async () => {
      if (!hasFilters) {
        setSearchedProducts([]);
        return;
      }
      try {
        setLoading(true);
        const res = await getProducts({ search: search.trim(), category, sort: 'rating_desc', limit: 40 });
        if (!active) return;
        setSearchedProducts(Array.isArray(res.data?.products) ? res.data.products : []);
      } catch (error) {
        if (!active) return;
        setSearchedProducts([]);
      } finally {
        if (active) setLoading(false);
      }
    };

    loadFiltered();
    return () => {
      active = false;
    };
  }, [hasFilters, search, category]);

  return (
    <div className="space-y-8">
      {quickCategories.length > 0 ? (
        <section className={`${isDarkMode ? 'bg-black' : 'bg-white'}`}>
          <div
            ref={categoriesScrollerRef}
            onWheel={handleCategoryWheel}
            className="overflow-x-auto hide-scrollbar scroll-smooth touch-pan-x"
          >
            <div className="relative inline-flex min-w-full items-stretch border-b border-gray-200 dark:border-gray-800 snap-x snap-mandatory [scroll-padding-inline:12px]">
              <button
                type="button"
                onClick={() => {
                  const params = new URLSearchParams(searchParams);
                  params.delete('category');
                  setSearchParams(params);
                }}
                className={`group relative snap-start flex-shrink-0 w-24 px-2 pt-2 pb-3 text-center transition-all duration-300 ${
                  !category ? 'text-gray-900 dark:text-white' : 'text-gray-600 dark:text-gray-300'
                }`}
              >
                <div className={`mx-auto mb-1.5 w-10 h-10 rounded-xl flex items-center justify-center text-2xl ${!category ? (isDarkMode ? 'bg-white/10' : 'bg-blue-100') : (isDarkMode ? 'bg-white/5' : 'bg-gray-100')}`}>🛍️</div>
                <div className="text-sm leading-tight font-semibold truncate">For You</div>
              </button>

              {quickCategories.map((cat) => {
                const active = category === cat;
                return (
                  <button
                    key={cat}
                    type="button"
                    onClick={() => {
                      const params = new URLSearchParams(searchParams);
                      params.set('category', cat);
                      setSearchParams(params);
                    }}
                    className={`group relative snap-start flex-shrink-0 w-24 px-2 pt-2 pb-3 text-center transition-all duration-300 ${
                      active ? 'text-gray-900 dark:text-white' : 'text-gray-600 dark:text-gray-300'
                    }`}
                  >
                    <div className={`mx-auto mb-1.5 w-10 h-10 rounded-xl flex items-center justify-center text-2xl ${active ? (isDarkMode ? 'bg-white/10' : 'bg-blue-100') : (isDarkMode ? 'bg-white/5' : 'bg-gray-100')}`}>
                      {getCategoryIcon(cat)}
                    </div>
                    <div className="text-sm leading-tight font-medium truncate">{cat}</div>
                  </button>
                );
              })}
              <span
                className="pointer-events-none absolute bottom-0 h-1 w-[84px] rounded-full bg-blue-600 transition-transform duration-300 ease-out"
                style={{ transform: `translateX(${activeTabIndex * 96 + 6}px)` }}
                aria-hidden="true"
              />
            </div>
          </div>
        </section>
      ) : null}

      <section>
        <div className="flex items-center justify-between mb-3">
          <h2 className={`text-xl font-bold ${isDarkMode ? 'text-white' : 'text-gray-900'}`}>Home Highlights</h2>
          <button type="button" onClick={() => navigate('/')} className="text-sm font-semibold text-blue-600">Reset</button>
        </div>

        {loading ? (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
            {Array.from({ length: 4 }).map((_, i) => (
              <div key={i} className={`h-64 rounded-xl animate-pulse ${isDarkMode ? 'bg-white/10' : 'bg-gray-200'}`} />
            ))}
          </div>
        ) : hasFilters ? (
          searchedProducts.length > 0 ? (
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
              {searchedProducts.map((product, idx) => (
                <ProductCard key={product._id || idx} product={product} index={idx} />
              ))}
            </div>
          ) : (
            <div className={`rounded-xl border p-6 text-center ${isDarkMode ? 'border-white/10 text-gray-300' : 'border-gray-200 text-gray-600'}`}>
              Koi product nahi mila.
            </div>
          )
        ) : featured.length > 0 ? (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
            {featured.slice(0, 8).map((product, idx) => (
              <ProductCard key={product._id || idx} product={product} index={idx} />
            ))}
          </div>
        ) : (
          <div className={`rounded-xl border p-6 text-center ${isDarkMode ? 'border-white/10 text-gray-300' : 'border-gray-200 text-gray-600'}`}>
            Products abhi empty hain. Naye products add hone ke baad yahan show honge.
          </div>
        )}
      </section>
    </div>
  );
};

export default HomeRebuild;
